s, 320)) . "' WHERE config_name = 'bblivechat'"); $cache->destroy('_bblivechat'); trigger_error($user->lang('CONFIG_UPDATED') . adm_back_link($this->u_action)); } } if (!$config['bblivechat_installed']) { $template->assign_var('AC_INSTALL', true); } else { $options = ''; $mp3path = dirname(__DIR__) . '/chat/media/sounds/'; $mp3len = strlen($mp3path); $sounds = glob($mp3path . '*.mp3'); if (!empty($sounds)) { foreach ($sounds as $sound) { $template->assign_block_vars('sounds', [ 'SFILE' => substr($sound, $mp3len), 'SOUND' => substr($sound, $mp3len, -4), ]); } } for($i=0; $i<6; $i++) { $template->assign_var("AC_SOUND{$i}", substr($this->defaults['sounds'][$i], 0, -4)); } $template->assign_vars(array( 'AC_CLOSED' => $defaults[0], 'AC_STANDALONE' => 'bblc', 'AC_CHANNELNAME' => $defaults[2], 'AC_CHATBOTNAME' => $defaults[3], 'AC_PRIVATEROOMS' => $defaults[4], 'AC_PRIVATEMESSAGES' => $defaults[5], 'AC_DELETEMESSAGES' => $defaults[6], 'AC_INACTIVE' => $defaults[7], 'AC_INACTIVECHECK' => $defaults[8], 'AC_BANTIME' => $defaults[9], 'AC_REQUESTLIMIT' => $defaults[10], 'AC_MAXUSERS' => $defaults[11], 'AC_MESSAGESIZE' => $defaults[12], 'AC_FLOODRATE' => $defaults[13], 'AC_REFRESHRATE' => $defaults[14], 'AC_AVATARS' => $defaults[15], 'AC_ANNOUNCE' => $defaults[16], 'AC_SHOWCHANNEL' => $defaults[17], 'AC_ADDON_SETTINGS' => \sitesplat\apply_filters('bblc_display_acp_settings', ''), 'AC_CSSMT' => filemtime(dirname(__DIR__) . '/adm/style/bblivechat.css'), )); } return $error; } protected function rooms($id, $mode) { global $db, $user, $request, $config, $template, $phpbb_container; $error = []; $room_id = $request->variable('id', '0'); $action = $request->variable('action', ''); switch ($action) { case 'add': if (count($this->defaults['rooms']) == 32) { trigger_error($user->lang('BBLIVECHAT_ERR_MAX_ROOMS'), E_USER_WARNING); } $error = $this->manage_room('add'); break; case 'edit': $error = $this->manage_room('edit', $room_id); break; case 'delete_image': $this->delete_image('image')