ent_id, 'module_langname' => 'VIEW_FORUM_LOGS', 'module_mode' => 'logs', 'module_auth' => 'acl_a_board', ]; $this->module_manager->update_module_data($data); $cache->destroy('_modules_acp'); $config->set('bblivechat_installed', 'yes'); } protected function reorder() { global $request, $user, $db; $error = []; $order = $request->variable('sort_order', ''); if (!check_form_key('sitesplat/bblivechat') || !$order) { $error[] = $user->lang('FORM_INVALID'); } $order_ary = json_decode(htmlspecialchars_decode($order), true); if (empty($order_ary)) { $error[] = $user->lang('ORDER_DATA_INVALID'); } if (!count($error)) { $newrooms = []; foreach ($order_ary as $room) { $newrooms += [$room => $this->defaults['rooms'][$room]]; } $this->defaults['rooms'] = $newrooms; $this->update_rooms_config(); $error[] = $user->lang('REORDER_SUCCESS'); } return $error; } protected function manage_room($action, $room_id = false) { global $db, $user, $request, $config, $template; $data = [ 'name' => str_replace('"', "'", $request->variable('name', '', true)), 'desc' => $request->variable('desc', '', true), 'classes' => $request->variable('classes', '', true), 'image' => '', 'cover' => $request->variable('cover', 1, true), 'announcement' => $request->variable('announcement', '', true), 'groups' => $request->variable('groups', [0]), ]; $errors = $names = $old_data = []; foreach ($this->defaults['rooms'] as $rid => $room) { $names[$rid] = $room['name']; } if ($action == 'delete' || $request->is_set_post('submit')) { if ($room_id !== false) { $old_data = $this->defaults['rooms'][$room_id]; unset($names[$room_id]); } else if (count($this->defaults['rooms'])) { $room_id = max(array_keys(($this->defaults['rooms']))) + 1; } else { $room_id = 1; } if ($action != 'delete') { if (!check_form_key('sitesplat/bblivechat')) { $errors[] = 'FORM_INVALID'; } if (empty($data['name'])) { $errors[] = 'NAME_REQUIRED'; } else { if (is_numeric($data['name'][0])) { $errors[] = 'NAME_STARTS_WITH_NUMBER'; } if (utf8_strlen($data['name']) > 60) { $errors[] = 'NAME_TOO_LONG'; } if (in_array($data['name'], array_values($names))) { $errors[] = 'NAME_ALREADY_TAKEN'; } } if (utf8_strlen($data['desc']) > 255) { $errors[] = 'DESC_TOO_LONG'; } if (utf8_strlen($data['classes']) > 255) { $errors[] = 'CLASSES_TOO_LONG'; } if (empty($data['groups'])) { $errors[] = 'GROUPS_AT_LEAST_ONE'; } $result = $this->handle_image_upload('image', $old_data); if ($result['file'] && !count($result['errors'])) { $errors = array_merge($errors, $result['errors']); $data['image'] = $result['file']->get('realname'); } else { $data['image'] = ($action == 'edit') ? $old_data['image'] : ''; } } list($errors, $data) = \sitesplat\apply_filters('bblc_handle_acp_rooms', [$errors, $data]); if (empty($errors)) { if ($action == 'delete') { unset($this->defaults['rooms'][$room_id]); if ($old_data['image']) { $this->fs->delete("{$this->root_path}/images/bblivechat/image/{$old_data['image']}"); } if ($old_data['cover']) { $this->fs->delete("{$this->root_path}/images/bblivechat/cover/{$old_data['cover']}"); } $db->sql_query("DELETE FROM bblc_messages WHERE channel = $room_id"); } else { $data['announcement'] = \sitesplat\emoji_convert($data['announcement']); $data['desc'] = \sitesplat\emoji_convert($data['desc']); $this->defaults['rooms'][$room_id] = $data; } $this->defaults['time'] = $this->now; $this->update_rooms_config(); trigger_error($user->lang('BBLIVECHAT_ROOM_' . strtoupper($action) . 'ED') . adm_back_link($this->u_action)); } else { $errors = array_map(array($user, 'lang'), $errors); } } else if ($room_id !== false) { $old_data = $this->defaults['rooms'][$room_id]; $data = [ 'name' => $old_data['name'], 'desc' => $old_data['desc'], 'classes' => $old_data['classes'], 'image' => $old_data['image'], 'cover' => $old_data['cover'], 'announcement' => $old_data['announcement'], 'groups' => (array) $old_data['groups'], ]; } foreach ($this->usergroups as $id => $name) { $template->assign_block_vars('groups', [ 'ID' => $id, 'NAME